const raw = $input.first().json;
const content = raw.choices?.[0]?.message?.content || '{}';
let parsed = {};
try { parsed = JSON.parse(content); } catch { parsed = {}; }

const ctx = $('Parse Article JSON').item.json;
const article = ctx.article || {};
const titleEn = String(article.titleEn || '').trim();

const fallbackQuery = (titleEn || 'crystal glassware dining table')
  .toLowerCase()
  .replace(/[^a-z0-9\s]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 80) || 'crystal glassware dining table';

let query = String(parsed.imageSearchQuery || parsed.query || fallbackQuery)
  .toLowerCase()
  .replace(/[^a-z0-9\s-]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 100);
if (!query) query = fallbackQuery;

let tags = Array.isArray(parsed.imageTags) ? parsed.imageTags : [];
tags = tags
  .map((t) => String(t || '').toLowerCase().replace(/[^a-z0-9]/g, ''))
  .filter((t) => t.length > 2)
  .slice(0, 5);
if (!tags.length) {
  tags = query.split(' ').filter((t) => t.length > 2).slice(0, 4);
}
if (!tags.length) tags = ['crystal', 'glassware', 'tableware'];

const slug = String(article.slug || ctx.slug || 'blog')
  .toLowerCase()
  .replace(/[^a-z0-9-]+/g, '-')
  .replace(/-+/g, '-')
  .replace(/^-|-$/g, '') || 'blog';

return [{
  json: {
    ...ctx,
    imageSearchQuery: query,
    imageTags: tags,
    imageAltFa: parsed.imageAltFa || article.titleFa || ctx.selectedKeyword,
    imageAltEn: parsed.imageAltEn || article.titleEn || query,
    thumbnailFileName: `${slug}-thumbnail.jpg`,
  },
}];

const ctx = $input.first().json;
const unsplashKey = String($env.UNSPLASH_ACCESS_KEY || '').trim();
const query = ctx.imageSearchQuery || 'crystal glassware';
const tags = Array.isArray(ctx.imageTags) && ctx.imageTags.length
  ? ctx.imageTags
  : query.split(' ').slice(0, 4);

let imageUrl = `https://loremflickr.com/1200/800/${tags.join(',')}`;
let imageSource = 'loremflickr';

if (unsplashKey) {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://api.unsplash.com/search/photos',
      qs: {
        query,
        per_page: 1,
        orientation: 'landscape',
        content_filter: 'high',
      },
      headers: {
        Authorization: `Client-ID ${unsplashKey}`,
      },
      json: true,
    });
    const direct = res?.results?.[0]?.urls?.regular || res?.results?.[0]?.urls?.full;
    if (direct) {
      imageUrl = direct;
      imageSource = 'unsplash';
    }
  } catch (e) {
    imageSource = 'loremflickr-fallback';
  }
}

return [{
  json: {
    ...ctx,
    imageUrl,
    imageSource,
  },
}];

const item = $input.first();
const ctx = $('Resolve Image URL').item.json;

if (!item.binary?.data) {
  // Still create draft without thumbnail if download failed
  return [{
    json: { ...ctx, hasThumbnail: false },
  }];
}

const bin = item.binary.data;
item.binary.data = {
  ...bin,
  fileName: ctx.thumbnailFileName || 'blog-thumbnail.jpg',
  fileExtension: 'jpg',
  mimeType:
    bin.mimeType && bin.mimeType !== 'application/octet-stream'
      ? bin.mimeType
      : 'image/jpeg',
};

return [{
  json: { ...ctx, hasThumbnail: true },
  binary: item.binary,
}];

const q = $input.first().json;
const errors = q.data?.errors || q.errors || ['Quality gate failed'];
throw new Error(Array.isArray(errors) ? errors.join(' | ') : String(errors));
